yijiang:shenxing.code:
{
    audio: 2,
    enable: "phaseUse",
    position: "he",
    filterCard: lib.filter.cardDiscardable,
    selectCard: 2,
    prompt: "弃置两张牌并摸一张牌",
    check(card) {
      var player = _status.event.player;
      if (!player.hasSkill("olbingyi") || player.hasSkill("olbingyi_blocker", null, null, false)) {
        return 4 - get.value(card);
      }
      var red = 0, black = 0, hs = player.getCards("h");
      for (var i of hs) {
        if (ui.selected.cards.includes(i)) {
          continue;
        }
        var color = get.color(i, player);
        if (color == "red") {
          red++;
        }
        if (color == "black") {
          black++;
        }
      }
      if (red > 2 && black > 2) {
        return 4 - get.value(card);
      }
      if (red == 0 || black == 0) {
        return 8 - get.value(card);
      }
      var color = get.color(card);
      if (black <= red) {
        return (color == "black" && get.position(card) == "h" ? 8 : 4) - get.value(card);
      }
      return (color == "red" && get.position(card) == "h" ? 8 : 4) - get.value(card);
    },
    async content(event, trigger, player) {
      await player.draw();
    },
    ai: {
      order: 9,
      result: {
        player(player, target) {
          if (!ui.selected.cards.length) {
            return 1;
          }
          if (!player.hasSkill("olbingyi") || player.hasSkill("olbingyi_blocker", null, null, false)) {
            return 1;
          }
          var red = 0, black = 0, hs = player.getCards("h");
          for (var i of hs) {
            if (ui.selected.cards.includes(i)) {
              continue;
            }
            var color = get.color(i);
            if (color == "red") {
              red++;
            }
            if (color == "black") {
              black++;
            }
          }
          var val = 0;
          for (var i of ui.selected.cards) {
            val += get.value(i, player);
          }
          if (red == 0 || black == 0) {
            if (red + black == 0) {
              return 0;
            }
            var num = Math.min(
              red + black,
              game.countPlayer(function(current) {
                return current != player && get.attitude(player, current) > 0 && !current.hasSkillTag("nogain");
              })
            ) + 1;
            if (num * 7 > val) {
              return 1;
            }
          }
          if (val < 8) {
            return 1;
          }
          return 0;
        }
      }
    }
  }

sp:xiashu.code:
{
    audio: 2,
    trigger: { player: "phaseUseBegin" },
    direct: true,
    filter(event2, player2) {
      return player2.countCards("h") > 0;
    },
    async content(event2, trigger2, player2) {
      const hs = player2.getCards("h");
      let maxval = 0;
      for (let i = 0; i < hs.length; i++) {
        maxval = Math.max(maxval, get.value(hs[i]));
      }
      const result = await player2.chooseTarget(get.prompt2("xiashu"), lib.filter.notMe).set("ai", function(target2) {
        var player3 = _status.event.player;
        var maxval2 = _status.event.maxval;
        var dh = target2.countCards("h") - player3.countCards("h");
        var att = get.attitude(player3, target2);
        if (target2.hasSkill("qingjian")) {
          return false;
        }
        if (dh <= 0) {
          return 0;
        }
        if (att > 0) {
          return 0.1;
        }
        if (maxval2 >= 8) {
          return 0;
        }
        if (att == 0) {
          return 0.2;
        }
        if (dh >= 3) {
          return dh;
        }
        if (dh == 2) {
          if (maxval2 <= 7) {
            return dh;
          }
        }
        if (maxval2 <= 6) {
          return dh;
        }
        return 0;
      }).set("maxval", maxval).forResult();
      if (result.bool) {
        player2.logSkill("xiashu", result.targets);
        event2.target = result.targets[0];
        await player2.give(hs, event2.target);
      } else {
        event2.finish();
        return;
      }
      const hs2 = event2.target.getCards("h");
      if (!hs2.length) {
        event2.finish();
        return;
      }
      hs2.sort(function(a, b) {
        return get.value(b, player2, "raw") - get.value(a, player2, "raw");
      });
      const result2 = await event2.target.chooseCard([1, hs2.length], "展示至少一张手牌", true, "allowChooseAll").set("ai", function(card2) {
        var rand = _status.event.rand;
        var list = _status.event.list;
        if (_status.event.att) {
          if (ui.selected.cards.length >= Math.ceil(list.length / 2)) {
            return 0;
          }
          var value = get.value(card2);
          if (_status.event.getParent().player.isHealthy()) {
            value += (get.tag(card2, "damage") ? 1.5 : 0) + (get.tag(card2, "draw") ? 2 : 0);
          }
          return value;
        }
        if (ui.selected.cards.length >= Math.floor(list.length / 2)) {
          return 0;
        }
        return list.indexOf(card2) % 2 == rand ? 1 : 0;
      }).set("rand", Math.random() < 0.6 ? 1 : 0).set("list", hs2).set("att", get.attitude(event2.target, player2) > 0).forResult();
      const showNext = event2.target.showCards(result2.cards);
      event2.cards1 = result2.cards;
      event2.cards2 = event2.target.getCards("h", function(card2) {
        return !event2.cards1.includes(card2);
      });
      await showNext;
      let choice;
      const num1 = event2.cards1.length;
      const num2 = event2.cards2.length;
      if (get.attitude(event2.target, player2) > 0 && num1 >= num2) {
        choice = 0;
      } else if (num1 == num2) {
        choice = Math.random() < 0.45 ? 0 : 1;
      } else if (num1 > num2) {
        if (num1 - num2 == 1) {
          choice = Math.random() < 0.6 ? 0 : 1;
        } else {
          choice = 0;
        }
      } else {
        if (num2 - num1 == 1) {
          choice = Math.random() < 0.6 ? 1 : 0;
        } else {
          choice = 1;
        }
      }
      const result3 = await player2.chooseControl(function(event3, player3) {
        return _status.event.choice;
      }).set("choiceList", ["获得" + get.translation(event2.target) + "展示的牌", "获得" + get.translation(event2.target) + "未展示的牌"]).set("choice", choice).forResult();
      if (result3.index == 0) {
        await player2.gain(event2.cards1, event2.target, "give", "bySelf");
      } else {
        await player2.gain(event2.cards2, event2.target, "giveAuto", "bySelf");
      }
    },
    ai: {
      expose: 0.1
    }
  }

