          }
          return get.effect(target, { name: "sha", isCard: true }, player, target);
        }
      }
    },
    subSkill: {
      sha: {
        audio: "olpingtao",
        charlotte: true,
        onremove: true,
        marktext: "讨",
        intro: { content: "本回合使用的【杀】可弃置一枚“讨”并额外指定一个目标" },
        trigger: {
          player: "useCard1"
        },
        filter(event, player) {
