{
    audio: 2,
    trigger: {
      global: ["loseAfter", "cardsDiscardAfter", "loseAsyncAfter", "equipAfter"]
    },
    forced: true,
    priority: 10,
    filter(event, player) {
      if (player !== _status.currentPhase) {
        return false;
      }
      if (event.name.indexOf("lose") == 0) {
