        logTarget(event, player) {
          return player.getRoundHistory("sourceDamage", (evt) => evt.num > 0)?.map((evt) => evt.player).unique().filter((target) => target.isIn() && target.canUse({ name: "sha", isCard: true }, player, false, false)).sortBySeat();
        },
