        return (() => {
          switch (tag) {
            case "fireAttack":
              return ["sha", "huogong"];
            default:
              return [tag.slice("respond".length).toLowerCase()];
          }
        })().some((name2) => get.info("olsblucun").hiddenCard(player, name2));
      },
      order(item, player) {
        if (player && _status.event.type === "phase") {
          let max = 0, names = get.inpileVCardList((info) => {
            const name2 = info[2];
